import type { QRCodeSVGImageSettings } from './types';
import { DEFAULT_ICON_IMAGE_URL, ICON_RATIO } from './constants';

const calculateIconSize = (size: number) => Math.round(size * ICON_RATIO);

export const generateImageSettings = (size: number): QRCodeSVGImageSettings => {
    const iconSize = calculateIconSize(size);

    return {
        src: DEFAULT_ICON_IMAGE_URL,
        excavate: true,
        height: iconSize,
        width: iconSize,
    };
};
