import React, { useMemo } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import type { QRCodeProps } from './types';
import { DEFAULT_SIZE, QUALITY_LEVEL, ROLE } from './constants';
import { generateImageSettings } from './utils';

const QRCode = ({ url, size = DEFAULT_SIZE, ariaLabel, dataTrackTag = 'qrcode', dataTrackValue }: QRCodeProps) => {
  const imageSettings = useMemo(() => generateImageSettings(size), [size]);

  return (
    <QRCodeSVG
      value={url}
      size={size}
      level={QUALITY_LEVEL}
      aria-label={ariaLabel}
      role={ROLE}
      imageSettings={imageSettings}
      data-track-tag={dataTrackTag}
      data-track-value={dataTrackValue}
    />
  );
};

QRCode.displayName = 'QRCode';

export default QRCode;
